pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amt1, uint96 amt2, address actor) public {
        vm.assume(amt1 > 0);
        vm.assume(amt2 > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Initialize and set MinSum low enough to allow Collect
        c.Initialized();
        c.SetMinSum(0);

        vm.deal(actor, uint256(amt1) + uint256(amt2));

        // First deposit
        vm.prank(actor);
        c.Deposit{value: amt1}();

        // Second deposit (buggy version overwrites balance to amt2, reference accumulates amt1+amt2)
        vm.prank(actor);
        c.Deposit{value: amt2}();

        uint256 balBefore = c.balances(actor);

        // Collect exactly amt1 + amt2 (only reference can succeed; buggy M has balance = amt2 < amt1+amt2)
        uint256 collectAmt = uint256(amt1) + uint256(amt2);
        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        uint256 balAfter = c.balances(actor);

        // Reference: Collect succeeds AND balance decreases by exactly collectAmt.
        // Bug: Collect either reverts or (if amt2 >= amt1+amt2 which is impossible with amt1>0) behaves differently.
        assertTrue(ok && balAfter == balBefore - collectAmt);
    }
}

