pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 deposit0, uint96 deposit1, uint96 collectAmt, address actor) public {
        // Admissible domain: actor must be a normal EOA, deposits >0, collect <= first deposit,
        // and total deposits must still be >= MinSum (1 ether) after collectAmt is deducted from the first deposit.
        vm.assume(actor != address(0));
        vm.assume(deposit0 > 0);
        vm.assume(deposit1 > 0);
        vm.assume(collectAmt <= uint256(deposit0));

        vm.assume(uint256(deposit0) + uint256(deposit1) >= c.MinSum());

        // Ensure the contract is initialized (required by reference C)
        c.Initialized();

        // First deposit by actor
        vm.deal(actor, uint256(deposit0));
        vm.prank(actor);
        c.Deposit{value: uint256(deposit0)}();

        // Second deposit by actor (this is overwritten in the buggy version)
        vm.deal(actor, uint256(deposit1));
        vm.prank(actor);
        c.Deposit{value: uint256(deposit1)}();

        // Collect an amount no larger than the first deposit
        bool ok;
        vm.prank(actor);
        try c.Collect(uint256(collectAmt)) {
            ok = true;
        } catch {
            ok = false;
        }

        // The rule: Collect should succeed, and the balance after the successful collect MUST be > 0.
        // Reference C: balances[actor] = deposit0 + deposit1 - collectAmt >= deposit1 > 0 -> true.
        // Buggy C overwrites the second deposit, so balances[actor] = deposit1 - collectAmt which may be 0
        // or insufficient to meet MinSum, causing a revert (ok = false) or balance == 0.
        assertTrue(ok && c.balances(actor) > 0);
    }
}

