pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 firstDeposit, uint96 secondDeposit, uint112 collectAmt) public {
        // Restrict domain to ensure conditions are meaningful and avoid overflow/underflow
        firstDeposit = uint96(bound(firstDeposit, 1, type(uint96).max));
        secondDeposit = uint96(bound(secondDeposit, 1, type(uint96).max));
        // Ensure collect amount is not zero and does not exceed first deposit
        collectAmt = uint112(bound(collectAmt, 1, firstDeposit));

        address actor = address(0x1337);
        vm.deal(actor, uint256(firstDeposit) + uint256(secondDeposit) + 1 ether);

        // First deposit
        vm.startPrank(actor);
        c.Deposit{value: firstDeposit}();
        // Second deposit
        c.Deposit{value: secondDeposit}();

        // No need to set MinSum, it defaults to 1 ether which is satisfied
        // by the combined deposits

        // Collect an amount <= first deposit
        c.Collect(collectAmt);
        vm.stopPrank();

        // After two deposits and a collect of amount <= first deposit,
        // the balance of the caller must be strictly greater than zero.
        // The bug overwrites instead of accumulating, so balance becomes zero before collect,
        // causing a revert, and the balance check will fail.
        assertTrue(c.balances(actor) > 0, "Balance should be positive after partial collect");
    }
}

