pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;
    function setUp() public { 
        c = new C(); 
        reverter = new Reverter();
        c.Initialized();
    }
    function testFuzz_property(uint96 deposit1, uint96 deposit2, uint112 collectAmt) public {
        // Restrict domain to reasonable amounts that fit in balances mapping
        uint d1 = uint(deposit1);
        uint d2 = uint(deposit2);
        uint ca = uint(collectAmt);
        vm.assume(d1 > 0 && d2 > 0);
        vm.assume(ca > 0 && ca <= d1);
        vm.assume(d1 + d2 >= ca);

        address alice = makeAddr("alice");
        vm.deal(alice, d1 + d2);

        // First deposit
        vm.prank(alice);
        c.Deposit{value: d1}();

        // Second deposit
        vm.prank(alice);
        c.Deposit{value: d2}();

        // Record balance before collect
        uint balanceBefore = c.balances(alice);

        // Collect from reverter address with exact balance needed, which will fail external call
        vm.prank(alice);
        try c.Collect(ca) { 
            // Should not succeed
            assertTrue(false);
        } catch {
            // Collect reverted
        }

        // After failed collect, balance must be unchanged from before collect
        uint balanceAfter = c.balances(alice);
        assertTrue(balanceAfter == balanceBefore);
    }
}

